import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load textures via cached loaders
  const imageTexture = ctx.textureLoader.load(config.renderParams.imageUrl);
  const depthTexture = ctx.textureLoader.load(config.renderParams.depthMapUrl);

  imageTexture.colorSpace = THREE.SRGBColorSpace;
  depthTexture.colorSpace = THREE.LinearSRGBColorSpace;

  // Tessellated plane geometry for displacement
  const geometry = new THREE.PlaneGeometry(4.0, 2.5, 64, 64);

  // Material with displacement mapping
  const material = new THREE.MeshStandardMaterial({
    map: imageTexture,
    displacementMap: depthTexture,
    displacementScale: 0.18,
    metalness: 0,
    roughness: 1,
    toneMapped: true,
    transparent: true,
  });

  const plateMesh = new THREE.Mesh(geometry, material);
  plateMesh.castShadow = false;
  plateMesh.receiveShadow = false;
  group.add(plateMesh);

  // Caption text block group
  const captionGroup = new THREE.Group();
  captionGroup.position.set(-1.9, -0.95, 0.01);

  // Render text via MSDF font atlas
  if (ctx.fontAtlas) {
    const textLines = [
      {
        text: 'NOVA ATELIER / GENEVA',
        fontSize: 0.09,
        color: 0xffffff,
        y: 0,
      },
      {
        text: 'Time, Machined.',
        fontSize: 0.34,
        color: 0xe8ecf2,
        y: -0.25,
      },
      {
        text: 'Every case begins as a single billet of 904L steel.',
        fontSize: 0.13,
        color: 0xb0b8c8,
        y: -0.6,
      },
      {
        text: 'CALIBRE NA-01 / 72 HOUR RESERVE',
        fontSize: 0.09,
        color: 0x999aaa,
        y: -0.9,
      },
    ];

    textLines.forEach((line) => {
      const textMesh = ctx.fontAtlas.createTextMesh({
        text: line.text,
        fontSize: line.fontSize,
        color: line.color,
        anchorX: 'left',
        anchorY: 'top',
      });
      if (textMesh) {
        textMesh.position.y = line.y;
        captionGroup.add(textMesh);
      }
    });

    // Accent hairline bar between headline and body
    const barGeometry = new THREE.PlaneGeometry(0.75, 0.02);
    const barMaterial = new THREE.MeshBasicMaterial({
      color: 0xff2a38,
      emissive: 0xff2a38,
      emissiveIntensity: 1.8,
      toneMapped: false,
    });
    const bar = new THREE.Mesh(barGeometry, barMaterial);
    bar.position.y = -0.42;
    bar.position.z = 0.001;
    captionGroup.add(bar);
  }

  group.add(captionGroup);

  // Plate fade-in: 0 → 1 over 500ms, cubic-bezier easing
  material.opacity = 0;
  gsap.to(material, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic.inOut',
  });

  // Caption block rise-in: y +0.4 → 0 over 700ms, power3.out, delay 120ms
  const captionStartY = captionGroup.position.y;
  captionGroup.position.y += 0.4;
  gsap.to(captionGroup.position, {
    y: captionStartY,
    duration: 0.7,
    ease: 'power3.out',
    delay: 0.12,
  });

  // Apply parallax-scroll cinematic primitive
  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](group, { intensity: 0.35 });
  }

  // Resource cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    imageTexture.dispose();
    depthTexture.dispose();
    gsap.killTweensOf([material, captionGroup.position]);

    captionGroup.children.forEach((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material && child.material.dispose) {
        child.material.dispose();
      }
    });
  };

  group.userData.handlers = {};

  return group;
}
